function trailingAvg3(amounts){
  const out = [];
  for (let i = 0; i < amounts.length; i++){
    const start = Math.max(0, i - 3); // 2 PRECEDING AND CURRENT ROW
    const frame = amounts.slice(start, i + 1);
    const sum = frame.reduce((s, x) => s + x, 0);
    out.push(sum / frame.length);
  }
  return out;
}

